  notes: Note[];
  totalMatches: number;
  searchDurationMs: number;
}

export interface ISearchService {
  search(query: string, notes: Note[], options?: SearchOptions): SearchResult;
  highlightText(text: string, query: string): string; // 转义特殊正则符号，返回安全高亮 HTML
}
